svg.script:
// ---------- 1. Theme definitions ----------
var themes = {
  GreenPistachio: {
    bg:     ["#f0fdf4", "#dcfce7", "#bbf7d0"],
    card:   ["#ffffff", "#f0fdf4"],
    accent: ["#16a34a", "#22c55e", "#4ade80"],
    text:   "#14532d",
    border: "#22c55e",
    decor:  ["#22c55e", "#4ade80", "#86efac"]
  },
  PurpleNight: {
    bg:     ["#0f172a", "#1e1b4b", "#312e81"],
    card:   ["#1e293b", "#0f172a"],
    accent: ["#6366f1", "#8b5cf6", "#a78bfa"],
    text:   "#f8fafc",
    border: "#6366f1",
    decor:  ["#6366f1", "#8b5cf6", "#a78bfa"]
  },
  White: {
    bg:     ["#f8fafc", "#f1f5f9", "#e2e8f0"],
    card:   ["#ffffff", "#f8fafc"],
    accent: ["#0f172a", "#334155", "#64748b"],
    text:   "#0f172a",
    border: "#94a3b8",
    decor:  ["#cbd5e1", "#e2e8f0", "#94a3b8"]
  },
  OceanBlue: {
    bg:     ["#0c4a6e", "#075985", "#0369a1"],
    card:   ["#0e7490", "#155e75"],
    accent: ["#22d3ee", "#67e8f9", "#a5f3fc"],
    text:   "#ecfeff",
    border: "#22d3ee",
    decor:  ["#22d3ee", "#67e8f9", "#a5f3fc"]
  },
  SunsetOrange: {
    bg:     ["#7c2d12", "#9a3412", "#c2410c"],
    card:   ["#431407", "#7c2d12"],
    accent: ["#fb923c", "#fdba74", "#fed7aa"],
    text:   "#fff7ed",
    border: "#fb923c",
    decor:  ["#fb923c", "#fdba74", "#fed7aa"]
  }
};

// ---------- 2. Read parameters from URL ----------
function getParam(name, fallback) {
  try {
    var params = new URLSearchParams(window.location.search);
    var v = params.get(name);
    return v !== null && v !== "" ? v : fallback;
  } catch (e) {
    return fallback;
  }
}

var text  = getParam("text",  "Study Materials");
var theme = getParam("theme", "GreenPistachio");

// Fall back to default if theme name is unknown
if (!themes[theme]) theme = "GreenPistachio";
var t = themes[theme];

// ---------- 3. Apply theme ----------
function setStops(gradientId, colors) {
  var stops = document.querySelectorAll("#" + gradientId + " stop");
  for (var i = 0; i < stops.length && i < colors.length; i++) {
    stops[i].setAttribute("stop-color", colors[i]);
  }
}
setStops("bgGrad",     t.bg);
setStops("cardGrad",   t.card);
setStops("accentGrad", t.accent);

document.getElementById("decor1").setAttribute("fill", t.decor[0]);
document.getElementById("decor2").setAttribute("fill", t.decor[1]);
document.getElementById("decor3").setAttribute("fill", t.decor[2]);
document.getElementById("innerBorder").setAttribute("stroke", t.border);
document.getElementById("cardTitle").setAttribute("fill", t.text);

// ---------- 4. Apply text ----------
var titleEl = document.getElementById("cardTitle");
titleEl.textContent = text;

// ---------- 5. Recenter underline based on text length ----------
// Rough estimate: 28px font, average char width ~15.5px
var approxWidth = text.length * 15.5;
var w = Math.max(60, Math.min(approxWidth, 280));
var underline = document.getElementById("underline");
underline.setAttribute("width", w);
underline.setAttribute("x", 190 - w / 2);
